import unittest

from reports import export_csv


class ExportCsvTests(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(
            export_csv([{"a": 1, "b": "x"}], ["a", "b"]),
            "a,b\r\n1,x\r\n")

    def test_crlf_and_embedded_newlines(self):
        self.assertEqual(
            export_csv([{"a": "x\ny", "b": "p\rq"}], ["a", "b"]),
            'a,b\r\n"x\ny","p\rq"\r\n')

    def test_quote_doubling(self):
        self.assertEqual(
            export_csv([{"a": 'he said "hi"'}], ["a"]),
            'a\r\n"he said ""hi"""\r\n')

    def test_unicode_preserved(self):
        self.assertEqual(
            export_csv([{"a": "héllo ☃"}], ["a"]),
            "a\r\nhéllo ☃\r\n")

    def test_missing_and_none_become_empty(self):
        self.assertEqual(
            export_csv([{"a": None, "b": 2}], ["a", "b", "c"]),
            "a,b,c\r\n,2,\r\n")

    def test_non_string_values_str(self):
        self.assertEqual(
            export_csv([{"a": 3, "b": 1.5, "c": True}], ["a", "b", "c"]),
            "a,b,c\r\n3,1.5,True\r\n")

    def test_unselected_fields_ignored(self):
        self.assertEqual(
            export_csv([{"a": 1, "z": 9}], ["a"]),
            "a\r\n1\r\n")

    def test_empty_columns(self):
        self.assertEqual(export_csv([{"a": 1}], []), "\r\n")
        self.assertEqual(export_csv([], []), "\r\n")

    def test_empty_rows(self):
        self.assertEqual(export_csv([], ["a", "b"]), "a,b\r\n")

    def test_one_shot_generators(self):
        def rows():
            yield {"a": 1}
            yield {"a": 2}

        def cols():
            yield "a"

        self.assertEqual(export_csv(rows(), cols()), "a\r\n1\r\n2\r\n")

    def test_duplicate_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([], ["a", "a"])

    def test_non_string_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([], ["a", 1])
        with self.assertRaises(ValueError):
            export_csv([], [None])

    def test_inputs_not_mutated(self):
        rows = [{"a": 1, "b": 2}]
        cols = ["a", "b"]
        export_csv(rows, cols)
        self.assertEqual(rows, [{"a": 1, "b": 2}])
        self.assertEqual(cols, ["a", "b"])

    def test_columns_iterable_not_consumed_for_caller(self):
        cols = (c for c in ["a"])
        export_csv([], cols)
        # Generator is consumed by design, but rows must not be touched when empty.
        self.assertEqual(export_csv([], ["x"]), "x\r\n")


if __name__ == "__main__":
    unittest.main()
